// updateBody turns removal of a previously configured nullable attribute into an explicit JSON null.
func (r *AlertResource) updateBody(ctx context.Context, config, plan, state AlertModel) map[string]interface{} {
	body := r.bodyForUpdate(ctx, config)
	if !state.Value.IsNull() && !state.Value.IsUnknown() && plan.Value.IsNull() {
		body["value"] = nil
	}
	if !state.StringValue.IsNull() && !state.StringValue.IsUnknown() && plan.StringValue.IsNull() {
		body["string_value"] = nil
	}
	if !state.CheckPeriod.IsNull() && !state.CheckPeriod.IsUnknown() && plan.CheckPeriod.IsNull() {
		body["check_period"] = nil
	}
	if !state.IncidentCause.IsNull() && !state.IncidentCause.IsUnknown() && plan.IncidentCause.IsNull() {
		body["incident_cause"] = nil
	}
	if !state.IncidentName.IsNull() && !state.IncidentName.IsUnknown() && plan.IncidentName.IsNull() {
		body["incident_name"] = nil
	}
	if !state.Metadata.IsNull() && !state.Metadata.IsUnknown() && plan.Metadata.IsNull() {
		body["metadata"] = nil
	}
	return body
}

func (r *AlertResource) Create(ctx context.Context, req resource.CreateRequest, resp *resource.CreateResponse) {
	defer func() { syncIdentity(ctx, resp.State, resp.Identity, alertIdentityNames, &resp.Diagnostics) }()
	defer rememberConfigured(ctx, req.Config, resp.Private, alertKeptOnRemoval, &resp.Diagnostics)
	var plan AlertModel
	resp.Diagnostics.Append(req.Plan.Get(ctx, &plan)...)
	var request AlertModel
	resp.Diagnostics.Append(configWithPlannedUnknowns(ctx, req.Config, req.Plan, nullValue(req.Plan.Raw.Type()), &request)...)
	request.AnomalySensitivity = plan.AnomalySensitivity             // its schema default travels when unset, so removing the line resets it
	request.AnomalyTrainingRangeDays = plan.AnomalyTrainingRangeDays // its schema default travels when unset, so removing the line resets it
	request.AnomalyTrigger = plan.AnomalyTrigger                     // its schema default travels when unset, so removing the line resets it
	request.Call = plan.Call                                         // its schema default travels when unset, so removing the line resets it
	request.ConfirmationPeriod = plan.ConfirmationPeriod             // its schema default travels when unset, so removing the line resets it
	request.CriticalAlert = plan.CriticalAlert                       // its schema default travels when unset, so removing the line resets it
	request.Email = plan.Email                                       // its schema default travels when unset, so removing the line resets it
	request.IncidentPerSeries = plan.IncidentPerSeries               // its schema default travels when unset, so removing the line resets it
	request.OnMissingData = plan.OnMissingData                       // its schema default travels when unset, so removing the line resets it
	request.Paused = plan.Paused                                     // its schema default travels when unset, so removing the line resets it
	request.Push = plan.Push                                         // its schema default travels when unset, so removing the line resets it
	request.RecoveryPeriod = plan.RecoveryPeriod                     // its schema default travels when unset, so removing the line resets it
	request.Sms = plan.Sms                                           // its schema default travels when unset, so removing the line resets it
	request.SourceMode = plan.SourceMode                             // its schema default travels when unset, so removing the line resets it
	request.SourcePlatforms = plan.SourcePlatforms                   // its schema default travels when unset, so removing the line resets it
	if resp.Diagnostics.HasError() {
		return
	}
	ctx = inTeam(ctx, plan.TeamId.ValueString())
	vars := map[string]string{}
	out, err := r.client.Create(ctx, alertBinding, vars, r.body(ctx, request))
	// The API took the create but its work didn't finish (wait.go): the object exists, so it goes
	// into state, which the error taints, and the next apply replaces it.
	unsettled, _ := err.(*waitError)
	if unsettled != nil {
		resp.Diagnostics.AddError("creating alert", err.Error())
		out, err = unsettled.Object, nil
	}
	if err != nil {
		addAPIError(&resp.Diagnostics, "creating alert", err, req.Plan.Raw.Type())
		return
	}
	if out == nil {
		out = map[string]interface{}{}
	}
	id, err := idFromResponse(out, "id")
	if err != nil {
		resp.Diagnostics.AddError("creating alert", err.Error())
		return
	}
	out["id"] = id
	// State = the plan with every unknown resolved from the API response (or nulled); known planned
	// values stay untouched so the apply result is always consistent with the plan.
	resp.State.Raw = stateFromPlan(req.Plan.Raw, nullValue(req.Plan.Raw.Type()), out)
}

func (r *AlertResource) Read(ctx context.Context, req resource.ReadRequest, resp *resource.ReadResponse) {
	defer func() { syncIdentity(ctx, resp.State, resp.Identity, alertIdentityNames, &resp.Diagnostics) }()
	var state AlertModel
	resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
	if resp.Diagnostics.HasError() {
		return
	}
	ctx = inStateTeam(ctx, state.TeamId.ValueString())
	vars := map[string]string{}
	vars["id"] = state.Id.ValueString()
	out, found, err := r.client.Get(ctx, alertBinding, vars)
	if err == nil && !found && state.TeamId.ValueString() == "" {
		// A moved or imported object doesn't know its team yet, and may be in another team than the
		// provider's team_id: read it by ID in whichever team the token reaches.
		// An API that refuses a read with no team (one for a token that reaches several teams) leaves
		// the first read's answer: not found under the provider's team. Any other failure is reported,
		// never taken for not found, so a passing outage doesn't drop the object from state.
		if retried, again, retryErr := r.client.Get(inNoTeam(ctx), alertBinding, vars); retryErr == nil {
			out, found = retried, again
		} else if !refusedWithoutTeam(retryErr) {
			err = retryErr
		}
	}
	if err != nil {
		addAPIError(&resp.Diagnostics, "reading alert", err, req.State.Raw.Type())
		return
	}
	if !found {
		resp.State.RemoveResource(ctx)
		return
	}
	populateAlert(ctx, &state, out)
	resp.Diagnostics.Append(resp.State.Set(ctx, &state)...)
}

